def solve(v: list[int]) -> int:
    st=[];best=0
    for i,h in enumerate(v+[0]):
        start=i
        while st and st[-1][1]>h:
            s,x=st.pop();best=max(best,x*(i-s));start=s
        if not st or st[-1][1]<h:st.append((start,h))
    return best

def solve(v: list[int]) -> int:
    if not v or v[0]==-1:return 0
    d,nxt,b=1,1,0
    for i,x in enumerate(v):
        if i==nxt:d+=1;nxt=nxt*2+1
